 31→function AppContent({
 32→  tables,
 33→  refreshTables,
 34→  sessionId,
 35→}: {
 36→  tables: TableInfo[];
 37→  refreshTables: () => Promise<void>;
 38→  sessionId: string;
 39→}) {
 40→  const { theme, toggleTheme } = useTheme();
 41→  const { language, setLanguage, t } = useTranslation();
 42→  const [queryResult, setQueryResult] = useState<QueryResult | null>(null);
 43→  const [error, setError] = useState<string | { key: string; params: Record<string, string> } | null>(null);
 44→  const [editorQuery, setEditorQuery] = useState<string | undefined>(
 45→    () => tables.length > 0 ? `SELECT * FROM "${tables[0].name}" LIMIT 100` : undefined
 46→  );
 47→  const [sidebarCollapsed, setSidebarCollapsed] = useState(() => window.innerWidth < 768);
 48→  const [agentOpen, setAgentOpen] = useState(true);
 49→  const [pendingSkillCommand, setPendingSkillCommand] = useState<string | null>(null);
 50→
 51→  useEffect(() => {
 52→    document.title = t('appTitle');
 53→  }, [t]);
 54→
 55→  useEffect(() => {
 56→    if (tables.length === 0) {
 57→      setQueryResult(null);
 58→      setError(null);
 59→      setEditorQuery(undefined);
 60→    }
 61→  }, [tables]);
 62→
 63→  const errorMessage = error
 64→    ? (typeof error === 'string' ? error : t(error.key, error.params))
 65→    : null;
 66→
 67→  const handleAgentToggle = () => {
 68→    setAgentOpen((prev) => !prev);
 69→  };
 70→
 71→  const handleLoadSample = useCallback(async () => {
 72→    setError(null);
 73→    try {
 74→      const response = await fetch('/api/upload/sample', { method: 'POST', headers: { 'X-Session-ID': sessionId } });
 75→      if (!response.ok) throw new Error('Failed to load sample dataset');
 76→      await refreshTables();
 77→      setEditorQuery('SELECT * FROM "titanic" LIMIT 100');
 78→    } catch (e) {
 79→      setError(e instanceof Error ? e.message : 'Failed to load sample dataset');
 80→    }
 81→  }, [refreshTables, sessionId]);
 82→
 83→  const handleFileUpload = useCallback(
 84→    async (files: File[]) => {
 85→      setError(null);
 86→
 87→      // Check for duplicate filenames within the batch
 88→      const batchDuplicates = findDuplicateFileNames(files);
 89→      if (batchDuplicates.length > 0) {
 90→        setError({ key: 'duplicateFilesInBatch', params: { names: batchDuplicates.join(', ') } });
 91→        return;
 92→      }
 93→
 94→      // Check for filenames that match already-uploaded table names
 95→      const existingNames = new Set(tables.map((tbl) => tbl.name));
 96→      const alreadyUploaded = files.filter((f) => existingNames.has(f.name)).map((f) => f.name);
 97→      if (alreadyUploaded.length > 0) {
 98→        setError({ key: 'duplicateFilesExist', params: { names: alreadyUploaded.join(', ') } });
 99→        return;
100→      }
101→
102→      let lastName = '';
103→      try {
104→        for (const file of files) {
105→          const formData = new FormData();
106→          formData.append('file', file);
107→          const response = await fetch('/api/upload', {
108→            method: 'POST',
109→            headers: { 'X-Session-ID': sessionId },
110→            body: formData,
111→          });
112→          if (!response.ok) {
113→            const errorData = await response.json();
114→            throw new Error(errorData.detail || 'Failed to upload file');
115→          }
116→          const result = await response.json();
117→          // Handle both single table and array of tables (Excel with multiple sheets)
118→          if (Array.isArray(result)) {
119→            lastName = result[result.length - 1]?.name || '';
120→          } else {
121→            lastName = result.name;
122→          }
123→        }
124→        await refreshTables();
125→        if (lastName) {
126→          setEditorQuery(`SELECT * FROM "${lastName}" LIMIT 100`);
127→        }
128→      } catch (e) {
129→        setError(e instanceof Error ? e.message : 'Failed to upload file');
130→      }
131→    },
132→    [refreshTables, sessionId, tables]
133→  );
134→
135→  const handleQueryExecute = useCallback(
136→    async (sql: string) => {
137→      setError(null);
138→      setQueryResult(null);
139→      try {
140→        const start = performance.now();
141→        const response = await fetch('/api/query', {
142→          method: 'POST',
143→          headers: { 'Content-Type': 'application/json', 'X-Session-ID': sessionId },
144→          body: JSON.stringify({ sql }),
145→        });
146→        const elapsed = performance.now() - start;
147→
148→        if (!response.ok) {
149→          const errorData = await response.json();
150→          throw new Error(errorData.detail || 'Query execution failed');
151→        }
152→
153→        const result = await response.json();
154→        setQueryResult({
155→          columns: result.columns,
156→          rows: result.rows,
157→          rowCount: result.rowCount,
158→          executionTimeMs: elapsed,
159→          resultType: result.resultType,
160→        });
161→        await refreshTables();
162→      } catch (e) {
163→        setError(e instanceof Error ? e.message : 'Query execution failed');
164→      }
165→    },
166→    [refreshTables, sessionId]
167→  );
168→
169→  const handleTableClick = useCallback((tableName: string) => {
170→    setEditorQuery(`SELECT * FROM "${tableName}" LIMIT 100`);
171→  }, []);
172→
173→  const handleTableDelete = useCallback(async (tableName: string) => {
174→    if (!confirm(t('deleteTableConfirm', { name: tableName }))) return;
175→    try {
176→      const response = await fetch(`/api/tables/${encodeURIComponent(tableName)}`, {
177→        method: 'DELETE',
178→        headers: { 'X-Session-ID': sessionId },
179→      });
180→      if (!response.ok) throw new Error('Failed to delete table');
181→      await refreshTables();
182→    } catch (e) {
183→      setError(e instanceof Error ? e.message : 'Failed to delete table');
184→    }
185→  }, [refreshTables, t, sessionId]);
186→
187→  const handleDeleteAll = useCallback(async () => {
188→    if (tables.length === 0) return;
189→    if (!confirm(t('deleteAllTablesConfirm'))) return;
190→    try {
191→      for (const table of tables) {
192→        const response = await fetch(`/api/tables/${encodeURIComponent(table.name)}`, {
193→          method: 'DELETE',
194→          headers: { 'X-Session-ID': sessionId },
195→        });
196→        if (!response.ok) throw new Error('Failed to delete table');
197→      }
198→      await refreshTables();
199→    } catch (e) {
200→      setError(e instanceof Error ? e.message : 'Failed to delete tables');
201→    }
202→  }, [tables, refreshTables, t, sessionId]);
203→
204→  const appClass = [
205→    'app',
206→    sidebarCollapsed ? 'app--sidebar-collapsed' : '',
207→  ].filter(Boolean).join(' ');
208→
209→  const themeIcon = theme === 'dark' ? (
210→    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
211→      <circle cx="12" cy="12" r="5" />
212→      <line x1="12" y1="1" x2="12" y2="3" />
213→      <line x1="12" y1="21" x2="12" y2="23" />
214→      <line x1="4.22" y1="4.22" x2="5.64" y2="5.64" />
215→      <line x1="18.36" y1="18.36" x2="19.78" y2="19.78" />
216→      <line x1="1" y1="12" x2="3" y2="12" />
217→      <line x1="21" y1="12" x2="23" y2="12" />
218→      <line x1="4.22" y1="19.78" x2="5.64" y2="18.36" />
219→      <line x1="18.36" y1="5.64" x2="19.78" y2="4.22" />
220→    </svg>
221→  ) : (
222→    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
223→      <path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z" />
224→    </svg>
225→  );
226→
227→  return (
228→    <div className={appClass}>
229→      <div className="app__sidebar-wrapper">
230→        <Sidebar tables={tables} onTableClick={handleTableClick} onTableDelete={handleTableDelete} onUpload={handleFileUpload} onDeleteAll={handleDeleteAll} collapsed={sidebarCollapsed} onToggle={() => setSidebarCollapsed((prev) => !prev)} onUseSkill={(name) => setPendingSkillCommand(name)} />
231→      </div>
232→      {agentOpen ? (
233→        <div className="app__agent-wrapper">
234→          <div className="app__header">
235→            <h1 className="app__title">{t('appTitle')}</h1>
236→            <div className="app__header-actions">
237→              <button
238→                className="app__lang-toggle"
239→                onClick={() => setLanguage(language === 'en' ? 'zh-TW' : 'en')}
240→                aria-label={language === 'en' ? t('switchToZh') : t('switchToEn')}
241→                title={language === 'en' ? t('switchToZh') : t('switchToEn')}
242→              >
243→                {language === 'en' ? 'EN' : '中'}
244→              </button>
245→              <button
246→                className="app__theme-toggle"
247→                onClick={toggleTheme}
248→                aria-label={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
249→                title={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
250→              >
251→                {themeIcon}
252→              </button>
253→              <button
254→                className="app__agent-toggle app__agent-toggle--active"
255→                onClick={handleAgentToggle}
256→              >
257→                {t('editorMode')}
258→              </button>
259→            </div>
260→          </div>
261→          {errorMessage && (
262→            <ErrorMessage message={errorMessage} onDismiss={() => setError(null)} />
263→          )}
264→          <AgentPanel
265→            tables={tables}
266→            onUpload={handleFileUpload}
267→            onLoadSample={handleLoadSample}
268→            pendingSkillCommand={pendingSkillCommand}
269→            onSkillCommandConsumed={() => setPendingSkillCommand(null)}
270→          />
271→        </div>
272→      ) : (
273→        <div className="app__editor-wrapper">
274→          <div className="app__header">
275→            <h1 className="app__title">{t('appTitle')}</h1>
276→            <div className="app__header-actions">
277→              <button
278→                className="app__lang-toggle"
279→                onClick={() => setLanguage(language === 'en' ? 'zh-TW' : 'en')}
280→                aria-label={language === 'en' ? t('switchToZh') : t('switchToEn')}
281→                title={language === 'en' ? t('switchToZh') : t('switchToEn')}
282→              >
283→                {language === 'en' ? 'EN' : '中'}
284→              </button>
285→              <button
286→                className="app__theme-toggle"
287→                onClick={toggleTheme}
288→                aria-label={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
289→                title={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
290→              >
291→                {themeIcon}
292→              </button>
293→              <button
294→                className="app__agent-toggle"
295→                onClick={handleAgentToggle}
296→              >
297→                {t('agentMode')}
298→              </button>
299→            </div>
300→          </div>
301→          <div className="app__mode-header">
302→            <span className="app__mode-title">{t('editorMode')}</span>
303→          </div>
304→          {errorMessage && (
305→            <ErrorMessage message={errorMessage} onDismiss={() => setError(null)} />
306→          )}
307→          <main className="app__main">
308→            {tables.length === 0 ? (
309→              <div className="app__empty">
310→                <FileUpload onUpload={handleFileUpload} onLoadSample={handleLoadSample} />
311→              </div>
312→            ) : (
313→              <>
314→                <QueryEditor
315→                  onExecute={handleQueryExecute}
316→                  initialQuery={editorQuery}
317→                />
318→                {queryResult?.resultType === 'markdown' ? (
319→                  <ResultMarkdown result={queryResult} />
320→                ) : (
321→                  <ResultsTable result={queryResult} />
322→                )}
323→              </>
324→            )}
325→          </main>
326→        </div>
327→      )}
328→    </div>
329→  );
330→}
331→
332→export default function App() {
333→  const sessionId = useSessionId();
334→  const [tables, setTables] = useState<TableInfo[]>([]);
335→  const [loading, setLoading] = useState(true);
336→  const [error, setError] = useState<string | null>(null);
337→  const refreshTables = useCallback(async () => {
338→    try {
339→      const response = await fetch('/api/tables', {
340→        headers: { 'X-Session-ID': sessionId },
341→      });
342→      if (!response.ok) throw new Error('Failed to fetch tables');
343→      const data = await response.json();
344→      setTables(data);
345→    } catch (e) {
346→      console.error('Failed to refresh tables:', e);
347→    }
348→  }, [sessionId]);
349→
350→  useEffect(() => {
351→    (async () => {
352→      try {
353→        const response = await fetch('/api/health');
354→        if (!response.ok) throw new Error('Backend is not available');
355→        await refreshTables();
356→      } catch (e) {
357→        setError(e instanceof Error ? e.message : 'Failed to connect to backend');
358→      } finally {
359→        setLoading(false);
360→      }
361→    })();
362→  }, [refreshTables]);
363→
364→  if (loading) {
365→    return <div className="app-loading">Connecting to backend...</div>;
366→  }
367→
368→  if (error) {
369→    return (
370→      <div className="app-error">Failed to connect: {error}</div>
371→    );
372→  }
373→
374→  return (
375→    <ConfigProvider>
376→      <LanguageProvider>
377→        <ThemeProvider>
378→          <AgentProvider refreshTables={refreshTables}>
379→            <AppContent tables={tables} refreshTables={refreshTables} sessionId={sessionId} />
380→          </AgentProvider>
381→        </ThemeProvider>
382→      </LanguageProvider>
383→    </ConfigProvider>
384→  );
385→}
