215→              text: data.prompt,
216→            });
217→            setMessages((prev) =>
218→              prev.map((m) =>
219→                m.id === assistantId
220→                  ? { ...m, segments: [...segmentsRef.current] }
221→                  : m
222→              )
223→            );
224→          },
225→          onSubagentEnd: (data) => {
226→            segmentsRef.current.push({
227→              type: 'subagent_end',
228→              subagentId: data.id,
229→              subagentName: data.name,
230→              chart_spec: data.chart_spec,
231→              sqlResults: data.sql_results,
