239→              )
240→            );
241→          },
242→          onDone: (newSessionId) => {
243→            if (newSessionId) sessionIdRef.current = newSessionId;
244→            if (flushTimerRef.current) {
245→              clearTimeout(flushTimerRef.current);
246→              flushTimerRef.current = null;
