454→              subagentId: data.id,
455→              subagentName: data.name,
456→              text: data.prompt,
457→            });
458→            setMessages((prev) =>
459→              prev.map((m) =>
460→                m.id === assistantId
461→                  ? { ...m, segments: [...segmentsRef.current] }
462→                  : m
463→              )
464→            );
465→          },
