467→            segmentsRef.current.push({
468→              type: 'subagent_end',
469→              subagentId: data.id,
470→              subagentName: data.name,
471→              chart_spec: data.chart_spec,
472→              sqlResults: data.sql_results,
473→              text: data.result,
474→            });
475→            setMessages((prev) =>
476→              prev.map((m) =>
477→                m.id === assistantId
478→                  ? { ...m, segments: [...segmentsRef.current] }
479→                  : m
480→              )
481→            );
482→          },
483→          onDone: (newSessionId) => {
484→            if (newSessionId) sessionIdRef.current = newSessionId;
485→            if (flushTimerRef.current) {
486→              clearTimeout(flushTimerRef.current);
487→              flushTimerRef.current = null;
488→            }
489→            flushText();
490→            if (currentTextRef.current.trim()) {
491→              segmentsRef.current.push({ type: 'answer', text: currentTextRef.current });
492→              currentTextRef.current = '';
493→            }
494→            setMessages((prev) =>
495→              prev.map((m) =>
496→                m.id === assistantId
497→                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
498→                  : m
499→              )
500→            );
501→            setIsStreaming(false);
502→            abortRef.current = null;
503→          },
504→          onError: (error) => {
505→            if (flushTimerRef.current) {
