508→            }
509→            flushText();
510→            if (currentTextRef.current.trim()) {
511→              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
512→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
513→              currentTextRef.current = '';
514→            }
515→            segmentsRef.current.push({ type: 'error', errorMessage: error });
516→            setMessages((prev) =>
517→              prev.map((m) =>
518→                m.id === assistantId
