530→            }
531→            flushText();
532→            if (currentTextRef.current.trim()) {
533→              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
534→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
535→              currentTextRef.current = '';
536→            }
