538→              type: 'user_question',
539→              questionData: data,
540→            });
541→            setMessages((prev) =>
542→              prev.map((m) =>
543→                m.id === assistantId
544→                  ? { ...m, segments: [...segmentsRef.current] }
545→                  : m
546→              )
547→            );
548→          },
