553→    },
554→    [isStreaming, messages, flushText, refreshTables, userSessionId]
555→  );
556→
557→  const deleteMessage = useCallback(
558→    (messageIndex: number) => {
559→      if (isStreaming) return;
560→
561→      // Store remaining messages as history for Langfuse context on next send
562→      setMessages((prev) => {
563→        const remaining = prev.slice(0, messageIndex);
564→        pendingHistoryRef.current = remaining
565→          .filter((m) => m.role === 'user' || m.role === 'assistant')
566→          .map((m) => ({ role: m.role, content: m.content }));
567→        return remaining;
568→      });
569→
570→      // Clear session so next message starts fresh
571→      sessionIdRef.current = null;
572→    },
573→    [isStreaming]
574→  );
575→
576→  const respondToQuestion = useCallback(
577→    async (questionId: string, answers: string[], freeText?: string) => {
578→      // Update the segment to show the user's answer
579→      const segIdx = segmentsRef.current.findIndex(
580→        (s) => s.type === 'user_question' && s.questionData?.questionId === questionId
581→      );
582→      if (segIdx !== -1) {
583→        segmentsRef.current[segIdx] = {
584→          ...segmentsRef.current[segIdx],
585→          userAnswer: answers,
586→          userFreeText: freeText,
587→        };
588→        setMessages((prev) =>
589→          prev.map((m) =>
590→            m.id === assistantIdRef.current
591→              ? { ...m, segments: [...segmentsRef.current] }
592→              : m
593→          )
594→        );
595→      }
596→
597→      // POST to backend
598→      try {
599→        await fetch('/api/chat/respond', {
600→          method: 'POST',
601→          headers: {
602→            'Content-Type': 'application/json',
603→            ...(userSessionId ? { 'X-Session-ID': userSessionId } : {}),
604→          },
605→          body: JSON.stringify({
606→            question_id: questionId,
607→            answers,
608→            free_text: freeText || null,
609→          }),
610→        });
611→      } catch (e) {
612→        console.error('Failed to respond to question:', e);
613→      }
614→    },
615→    [userSessionId]
616→  );
617→
618→  const loadMessages = useCallback((msgs: ChatMessage[], outgoingConversationId?: string | null, incomingConversationId?: string | null) => {
619→    // Abort any ongoing stream before loading a different conversation
620→    if (abortRef.current) {
621→      abortRef.current.abort();
622→      abortRef.current = null;
623→    }
624→    if (flushTimerRef.current) {
625→      clearTimeout(flushTimerRef.current);
626→      flushTimerRef.current = null;
627→    }
628→
629→    // Always prefer cached messages over API when available.  The cache
630→    // represents the most recent in-memory state (with rich segments,
631→    // streaming data, etc.) which is always fresher and more complete
632→    // than what the backend persisted to SQLite.
633→    let finalMsgs = msgs;
634→    if (incomingConversationId) {
635→      const cached = messagesCacheRef.current.get(incomingConversationId);
636→      if (cached && cached.length > 0) {
637→        finalMsgs = cached;
638→      }
639→      // Clear used cache entry so stale data doesn't persist forever
640→      messagesCacheRef.current.delete(incomingConversationId);
641→    }
642→
643→    // Save current messages to cache before replacing them.
644→    // Uses functional setMessages to read the latest state without
645→    // needing `messages` in the dependency array.
646→    setMessages(prev => {
647→      if (outgoingConversationId && prev.length > 0) {
648→        // Flush any pending text buffer into the streaming assistant message
649→        const pendingText = textBufferRef.current;
650→        const aId = assistantIdRef.current;
651→
652→        // Build finalized segments including any unflushed text
653→        let finalSegments = [...segmentsRef.current];
654→        const pendingSegmentText = currentTextRef.current + pendingText;
655→        if (pendingSegmentText.trim()) {
656→          const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
657→          finalSegments.push({ type: segType as ContentSegment['type'], text: pendingSegmentText });
658→        }
659→
660→        const cleaned = prev.map(m => {
661→          if (m.id === aId && m.isStreaming) {
662→            return {
663→              ...m,
664→              content: m.content + pendingText,
665→              isStreaming: false,
666→              currentPhase: undefined,
667→              segments: finalSegments.length > 0 ? finalSegments : m.segments,
668→            };
669→          }
670→          return m;
671→        });
672→        messagesCacheRef.current.set(outgoingConversationId, cleaned);
673→      }
674→      return finalMsgs;
675→    });
676→
677→    setIsStreaming(false);
678→    textBufferRef.current = '';
679→    currentTextRef.current = '';
680→    segmentsRef.current = [];
681→    assistantIdRef.current = '';
682→    phaseRef.current = 'thinking';
683→    sessionIdRef.current = null;
684→    pendingHistoryRef.current = null;
685→  }, []);
686→
687→  const clearMessages = useCallback((outgoingConversationId?: string | null) => {
688→    if (abortRef.current) {
689→      abortRef.current.abort();
690→      abortRef.current = null;
691→    }
692→    if (flushTimerRef.current) {
693→      clearTimeout(flushTimerRef.current);
694→      flushTimerRef.current = null;
695→    }
696→    setMessages(prev => {
697→      if (outgoingConversationId && prev.length > 0) {
698→        // Flush pending text and segments into the cached messages
699→        // (same logic as loadMessages cache save)
700→        const pendingText = textBufferRef.current;
701→        const aId = assistantIdRef.current;
702→        let finalSegments = [...segmentsRef.current];
703→        const pendingSegmentText = currentTextRef.current + pendingText;
704→        if (pendingSegmentText.trim()) {
705→          const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
706→          finalSegments.push({ type: segType as ContentSegment['type'], text: pendingSegmentText });
707→        }
708→        const cleaned = prev.map(m => {
709→          if (m.id === aId && m.isStreaming) {
710→            return {
711→              ...m,
712→              content: m.content + pendingText,
713→              isStreaming: false,
714→              currentPhase: undefined,
715→              segments: finalSegments.length > 0 ? finalSegments : m.segments,
716→            };
717→          }
718→          return m.isStreaming ? { ...m, isStreaming: false, currentPhase: undefined } : m;
719→        });
720→        messagesCacheRef.current.set(outgoingConversationId, cleaned);
721→      }
722→      return [];
723→    });
724→    setIsStreaming(false);
725→    textBufferRef.current = '';
726→    currentTextRef.current = '';
727→    segmentsRef.current = [];
728→    assistantIdRef.current = '';
729→    phaseRef.current = 'thinking';
730→    sessionIdRef.current = null;
731→    pendingHistoryRef.current = null;
732→  }, []);
733→
734→  return (
735→    <AgentContext.Provider
736→      value={{ messages, isStreaming, sendMessage, editMessage, deleteMessage, clearMessages, loadMessages, respondToQuestion }}
737→    >
738→      {children}
739→    </AgentContext.Provider>
740→  );
741→}
